-- Rareté des minéraux (très commun, commun, rare, très rare) : sert à doser la difficulté des jeux.
-- « Trouve le minéral » : très commun + commun ; quiz du jour : très commun + commun + rare. Classement : tools/minerals/rarete.py.
alter table public.minerals add column if not exists rarity text;
update public.minerals set rarity = 'tres_commun' where slug in ('agate', 'albite', 'almandin', 'amethyste', 'apatite', 'aragonite', 'azurite', 'baryte', 'beryl', 'biotite', 'calcedoine', 'calcite', 'citrine', 'cristal-de-roche', 'dolomite', 'epidote', 'fluorite', 'galene', 'goethite', 'graphite', 'gypse', 'halite', 'hematite', 'hornblende', 'jaspe', 'kaolinite', 'limonite', 'magnetite', 'malachite', 'microcline', 'muscovite', 'obsidienne', 'olivine', 'opale', 'orthose', 'pyrite', 'quartz', 'quartz-rose', 'schorl', 'serpentine', 'silex', 'soufre', 'sphalerite', 'talc');
update public.minerals set rarity = 'commun' where slug in ('actinote', 'aigue-marine', 'albatre', 'alexandrite', 'amazonite', 'ambre', 'ametrine', 'andalousite', 'andradite', 'anglesite', 'anhydrite', 'apophyllite', 'argent', 'arsenopyrite', 'augite', 'autunite', 'aventurine', 'bismuth', 'bixbite', 'borax', 'bornite', 'cassiterite', 'celestine', 'cerusite', 'chabazite', 'chalcanthite', 'chalcocite', 'chiastolite', 'chromite', 'chrysoberyl', 'chrysocolle', 'chrysoprase', 'chrysotile', 'cinabre', 'clinochlore', 'cordierite', 'corindon', 'cornaline', 'covellite', 'cuivre', 'cuprite', 'cymophane', 'demantoide', 'diamant', 'diopside', 'dioptase', 'disthene', 'dravite', 'elbaite', 'emeraude', 'enstatite', 'fluorapatite', 'fuchsite', 'goshenite', 'grossulaire', 'heliodore', 'heliotrope', 'hemimorphite', 'hessonite', 'hiddenite', 'howlite', 'hyalite', 'ilmenite', 'indicolite', 'iolite', 'jadeite', 'jais', 'kunzite', 'labradorite', 'lapis-lazuli', 'lazurite', 'lepidolite', 'magnesite', 'marcassite', 'melanite', 'mimetite', 'molybdenite', 'morganite', 'morion', 'natrolite', 'nephrite', 'oeil-de-tigre', 'oeuf-de-dinosaure', 'onyx', 'opale-de-feu', 'opale-noble', 'or', 'orpiment', 'pechblende', 'peridot', 'pierre-de-soleil', 'prehnite', 'pyrolusite', 'pyromorphite', 'pyrope', 'pyrrhotite', 'quartz-fume', 'quartz-rutile', 'realgar', 'rhodochrosite', 'rhodolite', 'rhodonite', 'rose-de-fer', 'rose-des-sables', 'rubis', 'rutile', 'sanidine', 'saphir', 'sardoine', 'scheelite', 'selenite', 'siderite', 'smithsonite', 'sodalite', 'spath-d-islande', 'spessartine', 'spinelle', 'spodumene', 'staurotide', 'stibine', 'stilbite', 'tanzanite', 'titanite', 'topaze', 'topaze-imperiale', 'torbernite', 'tourmaline-melon-d-eau', 'tremolite', 'tsavorite', 'turquoise', 'uraninite', 'uvarovite', 'vanadinite', 'verdelite', 'vermiculite', 'vesuvianite', 'vivianite', 'wolframite', 'wollastonite', 'wulfenite', 'zircon');
